fn double(s: &str) -> Result<i32, std::num::ParseIntError> {
    let n: i32 = s.parse()?;
    Ok(n * 2)
}

fn len(s: &String) -> usize { s.len() }
let s = String::from("abc");
println!("{}", len(&s));

let mut total = 0;
for i in 1..=3 {
    total += i;
}
let v = [10, 20, 30];
println!("{} {:?}", total, &v[1..]);

let s = String::from("a");
let m: std::collections::HashMap<i32, i32> = std::collections::HashMap::new();
println!("{} {}", s, m.len());

let x = 2;
let name = match x {
    1 => "one",
    _ => "other",
};
println!("{}", name);

fn square(n: i32) -> i32 {
    n * n
}
let add = |a: i32, b: i32| -> i32 { a + b };
println!("{} {}", square(3), add(1, 2));

fn longest<'a>(a: &'a str, b: &'a str) -> &'a str {
    if a.len() >= b.len() { a } else { b }
}
println!("{}", longest("ab", "abc"));
